//! display/dc/inc/hw/dpp.h + inc/hw/transform.h + dpp/dcn{10,20}_dpp.{h,c}
//! (Linux 6.18.55), with the `tf_regs`/`tf_shift`/`tf_mask` table of
//! dcn21_resource.c: the display pipe-and-plane processor (DPP) of Renoir's
//! resource pool. Renoir reuses the dcn20 DPP. One per pipe; the largest block.
//!
//! `dcn21_dpp_create` → `dpp2_construct` stores the instance, funcs identity,
//! caps and the register pointers, plus the line-buffer geometry; it writes no
//! register (the DPP programming — scaler, gamma, CM — is hwss-stage). The three
//! register structs and `DPP_REGS`/`DPP_SHIFT`/`DPP_MASK` are machine-generated
//! by `dcgen.py` from Linux' `TF_REG_LIST_DCN20(+COMMON_APPEND)` and
//! `TF_REG_LIST_SH_MASK_DCN20` (+ the debug lists), so the 224 registers x 4
//! pipes and 540 fields are Linux' own. Shift/mask fields a C designated
//! initializer sets twice keep the last macro, as C does.
#![allow(dead_code)]

use crate::regs::*;
use alloc::boxed::Box;

/// `#define LB_TOTAL_NUMBER_OF_ENTRIES` / `LB_BITS_PER_ENTRY` (dcn10_dpp.h).
const LB_TOTAL_NUMBER_OF_ENTRIES: i32 = 5124;
const LB_BITS_PER_ENTRY: i32 = 144;

/// `enum lb_pixel_depth` (inc/hw/hw_shared.h): a bit vector.
pub const LB_PIXEL_DEPTH_18BPP: i32 = 1;
pub const LB_PIXEL_DEPTH_24BPP: i32 = 2;
pub const LB_PIXEL_DEPTH_30BPP: i32 = 4;
pub const LB_PIXEL_DEPTH_36BPP: i32 = 8;

/// `enum dscl_data_processing_format` (inc/hw/transform.h).
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
#[repr(u32)]
pub enum dscl_data_processing_format {
    #[default]
    DSCL_DATA_PRCESSING_FIXED_FORMAT,
    DSCL_DATA_PRCESSING_FLOAT_FORMAT,
}

/// `struct dpp_caps` (inc/hw/transform.h): the `dscl_calc_lb_num_partitions` fn
/// pointer joins when that DSCL op is ported (hwss stage).
#[derive(Default, Clone, Copy)]
pub struct dpp_caps {
    pub dscl_data_proc_format: dscl_data_processing_format,
    pub max_lb_partitions: u32,
}

/// Which `dpp_funcs` vtable `dpp.funcs` points at (dcn20_dpp.c). Identity only;
/// the ops are hwss-stage.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum dpp_funcs {
    dcn20_dpp_funcs,
}

/// `struct dpp` (inc/hw/dpp.h): the base object. Linux' `ctx` is not stored (see
/// `clock_source`); the gamma/cursor/scaler run-time state joins grow-as-reached.
#[derive(Default)]
pub struct dpp {
    pub funcs: Option<dpp_funcs>,
    pub inst: u32,
    pub caps: Option<&'static dpp_caps>,
}

/// `struct dcn20_dpp` (dcn20_dpp.h): the concrete DPP. The scaler filter tables
/// and scaler/pwl run-time state join grow-as-reached.
#[derive(Default)]
pub struct dcn20_dpp {
    pub base: dpp,
    pub tf_regs: Option<&'static dcn2_dpp_registers>,
    pub tf_shift: Option<&'static dcn2_dpp_shift>,
    pub tf_mask: Option<&'static dcn2_dpp_mask>,
    pub lb_pixel_depth_supported: i32,
    pub lb_memory_size: i32,
    pub lb_bits_per_entry: i32,
}

/// `static struct dpp_caps dcn20_dpp_cap` (dcn20_dpp.c). `max_lb_partitions` is
/// left 0 by the designated initializer.
pub static DCN20_DPP_CAP: dpp_caps = dpp_caps {
    dscl_data_proc_format: dscl_data_processing_format::DSCL_DATA_PRCESSING_FLOAT_FORMAT,
    max_lb_partitions: 0,
};

/// `dpp2_construct` (dcn20_dpp.c): store the instance, funcs, caps and
/// registers, and the line-buffer geometry. Always succeeds here.
pub fn dpp2_construct(
    dpp: &mut dcn20_dpp,
    inst: u32,
    tf_regs: &'static dcn2_dpp_registers,
    tf_shift: &'static dcn2_dpp_shift,
    tf_mask: &'static dcn2_dpp_mask,
) -> bool {
    dpp.base.inst = inst;
    dpp.base.funcs = Some(dpp_funcs::dcn20_dpp_funcs);
    dpp.base.caps = Some(&DCN20_DPP_CAP);

    dpp.tf_regs = Some(tf_regs);
    dpp.tf_shift = Some(tf_shift);
    dpp.tf_mask = Some(tf_mask);

    dpp.lb_pixel_depth_supported =
        LB_PIXEL_DEPTH_18BPP | LB_PIXEL_DEPTH_24BPP | LB_PIXEL_DEPTH_30BPP | LB_PIXEL_DEPTH_36BPP;
    dpp.lb_bits_per_entry = LB_BITS_PER_ENTRY;
    dpp.lb_memory_size = LB_TOTAL_NUMBER_OF_ENTRIES;

    true
}

/// `dcn21_dpp_create` (dcn21_resource.c): allocate a `dcn20_dpp` for pipe `inst`
/// and construct it.
pub fn dcn21_dpp_create(inst: u32) -> Option<Box<dcn20_dpp>> {
    let mut dpp = Box::new(dcn20_dpp::default());
    if dpp2_construct(&mut dpp, inst, &DPP_REGS[inst as usize], &DPP_SHIFT, &DPP_MASK) {
        Some(dpp)
    } else {
        None
    }
}

